const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeKillamperpunnaPoint = ee.Geometry.Point(138.6, -28.9); // Approximate center of Lake Killamperpunna
  // Define a buffer around the point to represent the lake area for analysis
  const lakeArea = lakeKillamperpunnaPoint.buffer(5000); // 5 km buffer

  // Dates specified in the question (2025)
  const date1Start = '2025-06-20';
  const date1End = '2025-07-20'; // 1 month period around the first date
  const date2Start = '2025-09-15';
  const date2End = '2025-10-15'; // 1 month period around the second date

  // 2. Data Acquisition & Check
  // Sentinel-2 L2A data for water detection
  const collection = ee.ImageCollection('COPERNICUS/S2_SR');

  // Function to mask clouds from Sentinel-2 SR data.
  // Uses QA60 band to identify clouds.
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1
  }

  // Function to calculate MNDWI
  function addMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI'); // Green (B3) and SWIR1 (B11)
    return image.addBands(mndwi);
  }

  // Helper function to get and process data for a given period
  async function getWaterExtent(startDate, endDate, geometry) {
    let col = collection
      .filterBounds(geometry)
      .filterDate(startDate, endDate);

    const collectionSize = await col.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for period ${startDate} to ${endDate}.`);
      return { extent: null, size: 0, pixelCount: 0 };
    }

    col = col.map(maskS2clouds).map(addMNDWI);

    // Get a median composite to reduce noise and cloud effects
    const medianImage = col.median();

    // Check if the median image has any valid pixels
    const bandNames = medianImage.bandNames().getInfo();
    if (bandNames.length === 0) {
        console.log(`No valid bands in median image for period ${startDate} to ${endDate}. This indicates no unmasked pixels.`);
        return { extent: null, size: collectionSize, pixelCount: 0 };
    }

    const mndwiImage = medianImage.select('MNDWI');

    // Threshold MNDWI to classify water (MNDWI > 0 is common)
    const water = mndwiImage.gt(0).rename('water');

    // Calculate the number of water pixels
    const waterPixels = await water.reduceRegion({
      reducer: ee.Reducer.sum(), // Sum of water pixels (where water=1)
      geometry: geometry,
      scale: 100, // Use a finer scale for more accurate water extent, but not too fine to avoid timeout
      maxPixels: 1e9
    }).get('water').getInfo();

    // Calculate total area in square meters (pixel count * pixel area)
    const pixelAreaSqM = ee.Image.pixelArea().mask(water).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 100,
        maxPixels: 1e9
    }).get('area').getInfo();

    // Check if waterPixels is null (C3)
    if (waterPixels === null || pixelAreaSqM === null) {
      console.log(`Calculation failure for period ${startDate} to ${endDate}.`);
      return { extent: null, size: collectionSize, pixelCount: 0 };
    }

    // Check if valid pixels remain after masking (C2)
    if (waterPixels === 0) {
      console.log(`No water pixels found for period ${startDate} to ${endDate} after processing.`);
      return { extent: 0, size: collectionSize, pixelCount: 0 }; // Valid 0 extent
    }

    return { extent: pixelAreaSqM / 1e6, size: collectionSize, pixelCount: waterPixels }; // Convert to square kilometers
  }

  console.log("Analyzing water extent in Lake Killamperpunna...");

  const result1 = await getWaterExtent(date1Start, date1End, lakeArea);
  const result2 = await getWaterExtent(date2Start, date2End, lakeArea);

  // 5. Validation & Final Answer
  if (result1.size === 0 || result2.size === 0) {
    console.log("Error: One or both date ranges in 2025 yielded no images.");
    console.log("Earth Engine's data catalog contains historical data, not future data (e.g., 2025).");
    console.log("<answer>C1</answer>");
    return;
  }

  if (result1.extent === null || result2.extent === null) {
    console.log("Error: Water extent calculation failed for one or both periods.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Handle C2 case if one or both return 0 valid pixels after all processing, meaning no water found
  if (result1.pixelCount === 0 && result2.pixelCount === 0) {
    console.log(`Period 1 (2025-06): Images: ${result1.size}, Water Extent: ${result1.extent !== null ? result1.extent.toFixed(2) + ' km²' : 'N/A'}, Valid Pixels: ${result1.pixelCount}`);
    console.log(`Period 2 (2025-09): Images: ${result2.size}, Water Extent: ${result2.extent !== null ? result2.extent.toFixed(2) + ' km²' : 'N/A'}, Valid Pixels: ${result2.pixelCount}`);
    console.log("No valid water pixels found for either period after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // If one period has 0 water and the other has some water, it's a valid comparison
  // Print results
  console.log(`Period 1 (2025-06): Images: ${result1.size}, Water Extent: ${result1.extent.toFixed(2)} km², Valid Pixels: ${result1.pixelCount}`);
  console.log(`Period 2 (2025-09): Images: ${result2.size}, Water Extent: ${result2.extent.toFixed(2)} km², Valid Pixels: ${result2.pixelCount}`);

  if (result2.extent > result1.extent) {
    console.log("<answer>A</answer>"); // Yes
  } else {
    console.log("<answer>B</answer>"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
